class Solution{

    static int minute(int hhmm){
        return (hhmm/100)*60 + (hhmm%100);
    }
    public:
    int findPlatform(vector<int>& Arrival, vector<int>& Departure){
        vector<int> timeline(24*60 + 1);
        int n = Arrival.size();

        for(int i = 0; i < n; i++){
            timeline[minute(Arrival[i])]++;
            timeline[minute(Departure[i] + 1)]--;
        }

        int res = timeline[0];
        for(int i = 1; i < timeline.size(); i++){
            timeline[i] = timeline[i-1] + timeline[i];

            res = max(timeline[i], res);
        }

        return res;
    }
};
```

