        int len = Arrival.Count;
        List<(int start, int end)> trains = new List<(int start, int end)>();

        // create trains schedule
        for(int i = 0; i < len; i++) {
            trains.Add((Arrival[i], Departure[i]));
        }

        // sort schedule by arrival time
        trains.Sort((a, b) => a.start.CompareTo(b.start));

        int[] platFormBusy = new int[len];
        Array.Fill(platFormBusy, -1);

        int lastEnd = trains[0].end;
        platFormBusy[0] = lastEnd;
        for(int i = 1; i < len; i++) {

            if(trains[i].start > lastEnd) {
                lastEnd = trains[i].end;
                platFormBusy[0] = lastEnd;
            }
            else {
