                        platFormBusy[j] = trains[i].end;
                        break;
                    }
                }
            }
        }

        int numberOfPlatFormsUsed = 0;
        foreach(int i in platFormBusy) {

            if(i != -1) {
                numberOfPlatFormsUsed++;
            }
        }

        return numberOfPlatFormsUsed;

    }
}
